OPERATIONS_DASHBOARD = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>LLM Gateway Operations</title>
<style>
:root{color-scheme:dark;--bg:#10151d;--panel:#18212c;--line:#293747;--text:#e8eef5;--muted:#9aabba;--accent:#70d6bd;--warn:#ffcb76}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 ui-sans-serif,system-ui,-apple-system,sans-serif}
main{max-width:1180px;margin:0 auto;padding:32px 22px 64px}header{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:24px}
h1{font-size:clamp(25px,4vw,36px);letter-spacing:-.04em;margin:0}p{color:var(--muted);margin:5px 0 0}.controls,.card,.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px}
.controls{padding:14px;display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-bottom:18px}.field{display:grid;gap:5px;color:var(--muted);font-size:12px}.field input{width:min(440px,75vw)}input{background:#0f161e;border:1px solid var(--line);border-radius:8px;padding:10px;color:var(--text);font:inherit}
button{background:var(--accent);color:#09251e;border:0;border-radius:8px;padding:10px 16px;font-weight:700;cursor:pointer}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{padding:18px}.label{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em}.value{font-size:28px;font-weight:700;margin-top:6px;letter-spacing:-.03em}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.panel{padding:18px;min-width:0}h2{font-size:16px;margin:0 0 14px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:9px 7px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}th{color:var(--muted);font-weight:500}td:last-child,th:last-child{text-align:right}.status{color:var(--warn)}#message{min-height:22px;color:var(--muted);margin:8px 0}.empty{color:var(--muted);padding:12px 0}@media(max-width:760px){header{display:block}.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.value{font-size:24px}}
</style>
</head>
<body><main>
<header><div><h1>LLM Gateway</h1><p>Cost, provider health, and budget alert operations</p></div><span id="updated" class="label">Not refreshed</span></header>
<section class="controls"><label class="field">Admin bearer token<input id="token" type="password" autocomplete="off" placeholder="Paste a scoped admin key or OIDC token"></label><label class="field">Application filter<input id="application" placeholder="All applications"></label><button id="refresh">Refresh</button></section>
<div id="message" role="status"></div>
<section class="cards"><article class="card"><div class="label">Requests</div><div id="requests" class="value">—</div></article><article class="card"><div class="label">Estimated cost</div><div id="cost" class="value">—</div></article><article class="card"><div class="label">Failure rate</div><div id="failures" class="value">—</div></article><article class="card"><div class="label">Fallback rate</div><div id="fallbacks" class="value">—</div></article></section>
<section class="grid"><article class="panel"><h2>Spend by cost center</h2><div id="cost-centers"></div></article><article class="panel"><h2>Spend by provider and model</h2><div id="providers"></div></article><article class="panel"><h2>Budgets</h2><div id="budgets"></div></article><article class="panel"><h2>Provider health</h2><div id="health"></div></article><article class="panel"><h2>Webhook dead letters</h2><div id="webhooks"></div></article></section>
</main><script>
const $=id=>document.getElementById(id);const money=n=>'$'+Number(n||0).toFixed(4);const pct=n=>(Number(n||0)*100).toFixed(1)+'%';
function table(target,headers,rows){const root=$(target);if(!rows.length){root.innerHTML='<div class="empty">No data for this period.</div>';return}const t=document.createElement('table'),head=document.createElement('thead'),hr=document.createElement('tr');headers.forEach(h=>{const th=document.createElement('th');th.textContent=h;hr.append(th)});head.append(hr);t.append(head);const body=document.createElement('tbody');rows.forEach(row=>{const tr=document.createElement('tr');row.forEach(value=>{const td=document.createElement('td');td.textContent=value??'—';tr.append(td)});body.append(tr)});t.append(body);root.replaceChildren(t)}
async function refresh(){const token=$('token').value.trim();if(!token){$('message').textContent='Enter an admin key or OIDC token to load protected gateway data.';return}const headers={Authorization:'Bearer '+token};$('message').textContent='Loading…';try{const app=$('application').value.trim();const reportUrl=new URL('/v1/admin/report',location.origin);if(app)reportUrl.searchParams.set('application',app);const [r,b,p,w]=await Promise.all([fetch(reportUrl,{headers}),fetch('/v1/admin/budgets',{headers}),fetch('/v1/admin/providers',{headers}),fetch('/v1/admin/webhooks?status=dead_letter',{headers})]);for(const response of [r,b,p,w])if(!response.ok)throw new Error('Request denied ('+response.status+'). Check token scopes.');const [report,budgets,providers,webhooks]=await Promise.all([r.json(),b.json(),p.json(),w.json()]);$('requests').textContent=Number(report.requests||0).toLocaleString();$('cost').textContent=money(report.cost_usd);$('failures').textContent=pct(report.failure_rate);$('fallbacks').textContent=pct(report.fallback_rate);table('cost-centers',['Cost center','Requests','Cost'],(report.by_cost_center||[]).map(x=>[x.cost_center,Number(x.requests).toLocaleString(),money(x.cost_usd)]));const providerRows=(report.by_provider||[]).map(x=>['Provider: '+x.provider,Number(x.requests).toLocaleString(),money(x.cost_usd)]).concat((report.by_model||[]).map(x=>['Model: '+x.model,Number(x.requests).toLocaleString(),money(x.cost_usd)]));table('providers',['Provider / model','Requests','Cost'],providerRows);table('budgets',['Application','Spend / limit','Usage'],(budgets.applications||[]).map(x=>[x.tenant?x.tenant+':'+x.application:x.application,money(x.monthly_spend_usd)+' / '+(x.monthly_limit_usd==null?'—':money(x.monthly_limit_usd)),x.utilization==null?'—':pct(x.utilization)]));table('health',['Provider','State','Failure rate'],Object.entries(providers.providers||{}).map(([name,x])=>[name,x.state,pct(x.failure_rate)]));table('webhooks',['Application','Attempts','Last error'],(webhooks.events||[]).map(x=>[x.application,x.attempts,x.last_error]));$('updated').textContent='Updated '+new Date().toLocaleTimeString();$('message').textContent='';}catch(e){$('message').textContent=e.message}}
document.getElementById('refresh').addEventListener('click',refresh);document.getElementById('application').addEventListener('keydown',e=>{if(e.key==='Enter')refresh()});
</script></body></html>"""
